const referencia = new Date('2026-10-29T12:00:00-03:00');
return $input.all().map((item) => {
  const s = item.json;
  const dias = Math.ceil((new Date(s.vencimento+'T12:00:00-03:00')-referencia)/86400000);
  const situacao = s.renovado ? 'RENOVADO' : s.nao_vai_renovar ? 'NAO_RENOVA' : s.cobrado ? 'COBRADO' : 'A_CONFERIR';
  return { json: {...s, dias_ate_vencimento: dias, situacao} };
});

const registros = $input.all().map((i) => i.json);
const contagem = {A_CONFERIR:0,RENOVADO:0,COBRADO:0,NAO_RENOVA:0};
for(const registro of registros) contagem[registro.situacao]++;
return [{json:{
  projeto:'MonitorRenova — demonstração acadêmica',
  fonte:'8 clientes sintéticos dentro deste workflow; SEM acesso ao MySQL',
  data_referencia:'2026-10-29',
  competencia:'2026-11',
  total:registros.length,
  situacoes:contagem,
  enviou_mensagens:false,
  consultou_servicos_externos:false,
  observacao:'Fluxo demonstrativo executado manualmente; nenhum dado real processado.'
}}];
